(function(root){
'use strict';
const L=root.Lesson,T=L.T,M=root.TurtleModel,G=root.SubmissionGuide;
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='tta.y7.w3.theory.v1',CKey=KEY+'.teacher';
let s=null, storageOK=true,toastTimer=null,pdf=null,quizIndex=0;
const defaultConfig={assignmentTitle:'Year 7 Week 3 Theory - Turtle Trace',teamsUrl:'',gimkitUrl:'',screenshotOverrides:{}};
function load(key){try{return JSON.parse(localStorage.getItem(key)||'null');}catch(e){return null;}}
function cleanConfig(c){const n={...defaultConfig};if(!c||typeof c!=='object')return n;n.assignmentTitle=String(c.assignmentTitle||n.assignmentTitle).slice(0,150);for(const k of ['teamsUrl','gimkitUrl'])n[k]=validURL(c[k],k)?String(c[k]):'';n.screenshotOverrides={};for(const [k,v] of Object.entries(c.screenshotOverrides||{})){if(k.length<120&&v&&/^data:image\/(png|jpeg|webp);base64,/.test(v.src||'')&&v.src.length<1200000)n.screenshotOverrides[k]={src:v.src,caption:String(v.caption||'').slice(0,200),point:v.point?{x:Math.max(0,Math.min(1,Number(v.point.x)||0)),y:Math.max(0,Math.min(1,Number(v.point.y)||0))}:null};}return n;}
function validURL(url,type){if(!url)return true;try{const u=new URL(url);if(u.protocol!=='https:')return false;const host=u.hostname.toLowerCase();return(type==='gimkitUrl'?['gimkit.com']:['microsoft.com','office.com','microsoftonline.com','cloud.microsoft']).some(d=>host===d||host.endsWith('.'+d));}catch(e){return false;}}
let config=cleanConfig({...defaultConfig,...root.LESSON_CONFIG,...(load(CKey)||{})});
try{if(location.hash.startsWith('#setup=')){const v=JSON.parse(decodeURIComponent(escape(atob(location.hash.slice(7)))));config=cleanConfig({...config,...v});}}catch(e){}
function t(x){if(typeof x==='string')return E(x);const lang=s?.lang||document.querySelector('#entry-lang')?.value||'en';return E(x?.en||'')+(lang!=='en'&&x?.[lang]?'<span class="sub" lang="'+(lang==='zh'?'zh-Hans':'ko')+'">'+E(x[lang])+'</span>':'');}
function plain(x){return typeof x==='string'?x:(x?.en||'');}
function toast(msg){document.getElementById('toast').textContent=msg;clearTimeout(toastTimer);toastTimer=setTimeout(()=>document.getElementById('toast').textContent='',5500);}
function save(){if(!s)return;try{localStorage.setItem(KEY,JSON.stringify(s));storageOK=true;}catch(e){storageOK=false;}document.querySelectorAll('.saved').forEach(el=>{el.textContent=storageOK?'Saved on device':'Storage unavailable';el.style.color=storageOK?'':'#a43530';});}
function touch(core=true){if(!s)return;s.updatedAt=new Date().toISOString();if(core){s.evidenceVersion=(s.evidenceVersion||0)+1;if(s.pdfPreparedAt){s.pdfPreparedAt=null;s.pdfVersion=null;pdf=null;s.guideChecks={};toast('Your work changed. Prepare a new PDF before saving and submitting again.');}}save();}
function fresh(profile){return {schema:1,...profile,teacher:profile.name.trim().toLowerCase()==='teacher',startedAt:new Date().toISOString(),stage:0,sub:{main1:0,main2:0},fields:{},q:{},before:{},after:{},steps:{},traceAttempts:[],checkpoint:null,checkpointDraft:{points:[]},checkpointCorrections:[],support:[],guideChecks:{},guideStep:0,submissionHistory:[],overrides:[],evidenceVersion:0,pdfPreparedAt:null,pdfVersion:null,quiz:{answers:{},history:[]},extensionCode:'t.goto(80, 0)\nt.goto(80, -40)'};}
function hasQ(id){return !!s.q[id]?.history?.length;}
const main1Ids=['syntax','move','turn','pen','comment','hinge'];
function complete(id){switch(id){case'read':return hasQ('ready');case'do':return ['retrieval1','retrieval2','retrieval3'].every(hasQ);case'types':return ['knowledge','skills','understanding'].every(k=>s.before[k]!==undefined)&&!!s.fields.focus;case'main1':return main1Ids.every(hasQ);case'main2':return !!s.traceAttempts.length&&hasQ('compareA')&&hasQ('compareB')&&!!(s.fields.compareExplain||s.fields.compareSpoken)&&!!s.checkpoint;case'extension':return true;case'pitstop':return ['knowledge','skills','understanding'].every(k=>s.after[k]!==undefined)&&!!s.fields.evidence&&!!s.fields.nextAction;case'plenary':return hasQ('exit')&&!!(s.fields.exitExplain||s.fields.exitSpoken);case'submit':return !!s.guideChecks.confirm;case'challenge':return false;default:return false;}}
function missingCore(){return L.stages.filter(x=>!['extension','submit','challenge'].includes(x.id)&&!complete(x.id));}
function statePanel(a){return '<div class="starting"><span>Start: ('+a.x+', '+a.y+')</span><span>Facing: '+E(M.heading(a.h))+'</span><span>Pen: '+(a.pen?'down':'up')+'</span></div>';}
function codebox(code,current=0){return '<div class="codebox"><pre>'+String(code).split('\n').map((line,i)=>'<span class="code-line '+(current===i+1?'current':'')+'"><span class="line-no">'+(i+1)+'</span><span class="'+(line.trim().startsWith('#')?'code-comment':'')+'">'+E(line)+'</span></span>').join('')+'</pre></div>';}
function field(key,label,type='text',placeholder='',value){const v=value??s.fields[key]??'';return '<div class="field"><label for="f-'+E(key)+'">'+t(label)+'</label>'+(type==='textarea'?'<textarea id="f-'+E(key)+'" data-field="'+E(key)+'" maxlength="600" rows="3" placeholder="'+E(placeholder)+'">'+E(v)+'</textarea>':'<input id="f-'+E(key)+'" data-field="'+E(key)+'" type="'+type+'" maxlength="120" value="'+E(v)+'" placeholder="'+E(placeholder)+'">')+'</div>';}
function selectField(key,label,items,value){return '<div class="field"><label for="f-'+E(key)+'">'+t(label)+'</label><select id="f-'+E(key)+'" data-field="'+E(key)+'"><option value="">Choose…</option>'+items.map(o=>{const val=typeof o==='string'?o:o.value,txt=typeof o==='string'?o:o.label;return '<option value="'+E(val)+'" '+((value??s.fields[key])===val?'selected':'')+'>'+E(plain(txt))+(s.lang!=='en'&&txt?.[s.lang]?' / '+E(txt[s.lang]):'')+'</option>';}).join('')+'</select></div>';}
function read(text){return '<div class="read-panel"><div class="eyebrow">Read / notice</div><p>'+t(text)+'</p></div>';}
function question(id){const q=L.questions[id],a=s.q[id]||{},last=a.history?.at(-1),show=last&&last.value===a.value,labQ=[...main1Ids,'compareA','compareB'].includes(id),tested=root.TurtleIDE?.hasRun(id);return '<section class="question" id="q-'+id+'"><fieldset><legend>'+t(q.stem)+'</legend><div class="options">'+q.options.map((op,i)=>'<label class="option"><input type="radio" name="q-'+id+'" data-q="'+id+'" value="'+i+'" '+(a.value===i?'checked':'')+'><span>'+t(op)+'</span></label>').join('')+'<label class="option"><input type="radio" name="q-'+id+'" data-q="'+id+'" value="-1" '+(a.value===-1?'checked':'')+'><span>'+t(T('I am not sure yet','我还不确定','아직 잘 모르겠어요'))+'</span></label></div></fieldset><div class="button-row"><button data-act="check-q" data-id="'+id+'">'+t((labQ?T('Save prediction','保存预测','예측 저장'):T('Check my answer','检查答案','답 확인')))+'</button><small>'+(a.history?.length?'First attempt kept.':'Predict before checking.')+'</small></div>'+(show&&(!labQ||tested)?'<div class="feedback '+(last.value===q.correct?'good':'retry')+'"><strong>'+(last.value===q.correct?'That prediction works.':'Look again, then try a correction.')+'</strong><p>'+t(q.why)+'</p></div>':(show&&labQ?'<div class="feedback"><strong>Prediction saved.</strong><p>Run the Python below to test your idea. Your first answer stays in the report.</p></div>':''))+'</section>';}
function visual(id,unlocked){const ex=L.examples[id],states=M.trace(ex.code,ex.start),n=Math.min(s.steps[id]||0,states.length-1),st=states[n];return '<div class="visualiser">'+statePanel(ex.start)+'<div class="state"><div class="stat"><small>Position</small><strong>('+st.x+', '+st.y+')</strong></div><div class="stat"><small>Facing</small><strong>'+E(M.heading(st.h))+'</strong></div><div class="stat"><small>Pen</small><strong>'+(st.pen?'Down':'Up')+'</strong></div></div><figure>'+M.svg(st,ex.bounds||{})+'<figcaption>'+t(T('The arrow shows facing direction. Grid and arrow are teaching aids.','箭头表示朝向。坐标网格和箭头是教学辅助。','화살표는 바라보는 방향입니다. 격자와 화살표는 학습 보조입니다.'))+'</figcaption></figure><div class="buttons"><button class="small" data-act="reset-trace" data-id="'+id+'">Reset</button><small>Line '+n+' / '+(states.length-1)+'</small><button class="small primary" data-act="step-trace" data-id="'+id+'" '+(!unlocked||n===states.length-1?'disabled':'')+'>'+t(T('Reveal next step','显示下一步','다음 단계 보기'))+'</button></div>'+(!unlocked?'<p class="hint" style="padding:0 .8rem">'+t(T('Make and check your prediction first.','先预测并检查答案。','먼저 예측하고 답을 확인하세요.'))+'</p>':'')+'</div>';}
function goalsHTML(){return '<h2>WAGBA</h2><p class="wagba">'+t(L.goals.wagba)+'</p><dl>'+['knowledge','skills','understanding'].map(k=>'<dt>'+k+'</dt><dd>'+t(L.goals[k])+'</dd>').join('')+'</dl><div class="rule"><h2>Keywords</h2><p class="keywords">'+L.terms.map(v=>E(v[0])+(s?.lang==='zh'?' / '+E(v[1]):s?.lang==='ko'?' / '+E(v[2]):'')).join(' · ')+'</p></div><div class="challenge"><h2>Challenge</h2><p>'+t(L.goals.challenge)+'</p></div>';}
function languageOptions(lang){return ['en','zh','ko'].map((x,i)=>'<option value="'+x+'" '+(lang===x?'selected':'')+'>'+['English','English + 中文','English + 한국어'][i]+'</option>').join('');}
function deviceOptions(value=''){return [['','Choose your device…'],['ipad','iPad'],['android','Android tablet'],['windows','Laptop / computer — Windows'],['mac','Laptop — Mac'],['chromebook','Laptop — Chromebook']].map(([v,l])=>'<option value="'+v+'" '+(value===v?'selected':'')+'>'+l+'</option>').join('');}
function browserOptions(device,current){let a=device==='ipad'?['Safari','Chrome']:device==='android'?['Chrome','Other']:device==='mac'?['Safari','Chrome','Edge','Other']:device==='chromebook'?['Chrome']:['Chrome','Edge','Other'];return a.map(x=>'<option '+(x===current?'selected':'')+'>'+x+'</option>').join('');}
function landing(){const saved=load(KEY);s=null;document.getElementById('app').innerHTML='<main class="landing" id="main"><div class="landing-copy"><span class="lesson-label">YEAR 7 · TERM 1 · WEEK 3 THEORY</span><div class="landing-display"><button type="button" class="small screen-display-button" data-screen-action="open"><span class="aa">Aa</span> Display</button><small id="screen-landing-status">Auto screen fit</small></div><h1>Read.<br>Trace.<br>Predict.</h1><p class="lead">Understand the route before the Turtle moves.</p><p class="muted">Python Turtle · 60 minutes · Your own evidence</p><div class="routine"><span>Think</span>→<span>Check</span>→<span>Explain</span></div><div class="landing-mini">'+M.svg(M.trace('t.forward(80)\nt.right(90)\nt.forward(40)').at(-1))+'<div class="mini-caption"><span>Where will the next line go?</span><span>→</span></div></div></div><section class="landing-form"><h2>Start your lesson</h2><p class="muted">The layout fits your screen automatically. Check the suggested device below for your PDF saving guide.</p>'+(saved?.name?'<div class="notice"><strong>Continue '+E(saved.name)+' · '+E(saved.klass)+'</strong><div class="button-row"><button data-act="resume">Resume saved lesson</button></div><small>Not you? Start a new lesson below. Do not use another student’s answers.</small></div>':'')+'<form id="entry"><div class="field"><label for="entry-name">Your name</label><input id="entry-name" name="name" autocomplete="off" maxlength="60" required placeholder="First and last name"></div><div class="field"><label for="entry-class">Your class</label><input id="entry-class" name="klass" autocomplete="off" maxlength="30" placeholder="For example: 7A"></div><div class="field"><label for="entry-device">Your device</label><select id="entry-device" name="device">'+deviceOptions()+'</select><small id="device-suggestion"></small></div><div class="grid-two"><div class="field"><label for="entry-browser">Browser</label><select id="entry-browser" name="browser">'+browserOptions('windows','Chrome')+'</select></div><div class="field"><label for="entry-teams">Teams route</label><select id="entry-teams" name="teamsMode"><option value="app">Teams app</option><option value="browser">Teams in a browser</option></select></div></div><div class="field"><label for="entry-lang">Language support</label><select id="entry-lang" name="lang">'+languageOptions('en')+'</select></div><p class="error" id="entry-error" role="alert"></p><button class="primary start" type="submit">Start learning →</button><p class="hint space">Your answers stay in this browser. They are not sent to your teacher automatically. Use your school’s usual name format; do not enter passwords.</p><details><summary>Teacher access</summary><p class="hint">Enter <strong>teacher</strong> as the name to open all stages and teacher tools. This is a classroom convenience, not secure authentication.</p></details></form></section></main>';root.ScreenFit?.mount();}
function render(){root.TurtleIDE?.beforeRender();if(!s){landing();return;}const st=L.stages[s.stage],done=L.stages.filter(x=>!['extension','submit','challenge'].includes(x.id)&&complete(x.id)).length;
document.getElementById('app').innerHTML='<header class="topbar"><div class="brand"><span class="brand-badge">Y7</span><div><strong>Turtle Trace</strong><small>WEEK 3 · THEORY</small></div></div><div class="header-actions"><span class="saved">'+(storageOK?'Saved on device':'Storage unavailable')+'</span><select aria-label="Language support" id="lang">'+languageOptions(s.lang)+'</select><button class="small screen-display-button" data-screen-action="open" type="button"><span class="aa">Aa</span> Display</button><button class="small" data-act="reference">Command guide</button><button class="small" data-act="profile">'+E(s.teacher?'Teacher profile':s.name.split(' ')[0])+'</button>'+(s.teacher?'<button class="small dark" data-act="teacher">Teacher tools</button>':'')+'</div></header><div class="layout"><aside class="sidebar">'+goalsHTML()+'<button class="small" data-act="support">I need help</button></aside><div class="workspace"><details class="mobile-goals"><summary>WAGBA · Knowledge · Skills · Understanding</summary>'+goalsHTML()+'</details>'+(s.teacher?'<div class="teacher-banner"><strong>Teacher review</strong> · All stages open. Use Teacher tools for the answer key, submission screenshots and Gimkit setup.</div>':'')+(!storageOK?'<div class="notice warning">This browser is not saving progress. Keep this tab open and export your PDF before leaving.</div>':'')+'<nav class="stage-nav" aria-label="Lesson stages">'+L.stages.map((a,i)=>'<button data-act="stage" data-index="'+i+'" class="'+(i===s.stage?'active ':'')+(complete(a.id)&&a.id!=='extension'?'done':'')+'" '+(i===s.stage?'aria-current="step"':'')+'>'+E(a.name.en)+'</button>').join('')+'</nav><div class="progress-label"><span>'+done+' / 7 core stages attempted · completion is not a grade</span><span>'+E(s.klass)+' · '+E(s.device)+'</span></div><progress max="7" value="'+done+'" aria-label="Core stages attempted"></progress><main class="lesson-card" id="main" tabindex="-1"><div class="card-title"><div><div class="eyebrow">'+t(st.name)+'</div><h1>'+t(st.title)+'</h1></div><span class="tag">'+E(st.time)+(st.time.includes('–')?' min':'')+'</span></div>'+stageHTML(st.id)+'</main><div class="stage-footer"><button data-act="prev" '+(s.stage===0?'disabled':'')+'>← Back</button><span class="hint">'+t(T('Work carefully. Your first attempts stay in your report.','认真作答。报告会保留第一次尝试。','차근차근 풀어 보세요. 첫 시도는 보고서에 남습니다.'))+'</span><button class="primary" data-act="next" '+(s.stage===L.stages.length-1?'disabled':'')+'>'+t(T(s.stage===8?'Continue to challenge →':'Continue →',s.stage===8?'进入挑战 →':'继续 →',s.stage===8?'도전으로 →':'계속 →'))+'</button></div><div class="row between"><button class="quiet small" data-act="support">'+t(T('I need help','我需要帮助','도움이 필요해요'))+'</button><button class="quiet small" data-act="sources">Sources & privacy</button></div></div></div>';
save();root.TurtleIDE?.mount();root.ScreenFit?.mount();}
function stageHTML(id){switch(id){case'read':return missionHTML();case'do':return read(T('Use what you learned last week. A destination is not an extra movement. Pen up is not stop.','回顾上周知识：目的地不是额外移动，提笔不是停止。','지난 시간의 내용을 떠올리세요. 도착 위치는 추가 이동량이 아니고, 펜 올리기는 멈춤이 아닙니다.'))+['retrieval1','retrieval2','retrieval3'].map(question).join('');case'types':return reflectionHTML(false);case'main1':return main1HTML();case'main2':return main2HTML();case'extension':return extensionHTML();case'pitstop':return reflectionHTML(true);case'plenary':return question('exit')+field('exitExplain',T('Explain your prediction in one short sentence.','用一句简短的话解释预测。','짧은 한 문장으로 예측을 설명하세요.'),'textarea','After the turn…')+spoken('exitSpoken');case'submit':return submitHTML();case'challenge':return challengeHTML();}return '';}
function spoken(key){return '<label class="checkrow"><input type="checkbox" data-field="'+key+'" '+(s.fields[key]?'checked':'')+'><span>'+t(T('I explained aloud to my partner or teacher instead.','我改为向同伴或老师口头解释了。','짝이나 선생님에게 말로 설명했습니다.'))+'<small>This records your report of a spoken explanation. Audio is not recorded.</small></span></label>';}
function missionHTML(){return '<div class="grid-two"><div>'+read(T('A new student is following a route drawn by a Turtle program. The code runs, but does the line go where the programmer intended? Your job is to predict before revealing the output.','新同学正沿着 Turtle 程序画出的路线前进。代码能运行，但路线符合设计者的想法吗？你的任务是在显示结果之前预测。','새 학생이 Turtle 프로그램으로 그린 길을 따라갑니다. 코드는 실행되지만 생각한 길이 맞을까요? 결과를 보기 전에 예측하는 것이 오늘의 임무입니다.'))+'<div class="callout-big">'+t(T('A computer follows the instructions you write — not the ones you meant.','计算机执行你写出的指令，而不是你心里想的指令。','컴퓨터는 생각한 명령이 아니라 실제로 작성한 명령을 따릅니다.'))+'</div><p>'+t(T('Today you will also practise saving one PDF and turning it in through Teams.','今天还会练习保存一份 PDF，并通过 Teams 提交。','오늘은 PDF 한 개를 저장하고 Teams로 제출하는 연습도 합니다.'))+'</p></div><div class="panel"><div class="eyebrow">Check the starting state</div>'+statePanel({x:0,y:0,h:0,pen:true})+M.svg({x:0,y:0,h:0,pen:true,segments:[]})+'<p class="hint">'+t(T('Facing right is the starting direction unless a task says otherwise. Each task states its own starting position.','除非题目另有说明，开始时朝右。每题会说明起始位置。','별도 안내가 없으면 처음에는 오른쪽을 봅니다. 각 문제에 시작 위치가 주어집니다.'))+'</p></div></div>'+question('ready');}
function reflectionHTML(after){const map=after?s.after:s.before,opts=after?L.after:L.before;let out=read(after?T('Return to the same learning statements. Choose how each feels now, then show one piece of evidence. These are reflections, not ability labels or grades.','再次查看相同的学习目标，选择现在的状态，并指出一项证据。这是反思，不是能力标签或分数。','같은 학습 목표를 다시 살펴보세요. 현재 상태와 학습 근거를 고르세요. 능력이나 성적을 정하는 활동이 아닙니다.'):T('Think about three kinds of learning: what you know, what you can do, and what you can explain. Choose your own starting point for each.','思考三类学习：你知道什么、能做什么、能解释什么。分别选择起点。','무엇을 아는지, 무엇을 할 수 있는지, 무엇을 설명할 수 있는지 생각하며 시작점을 고르세요.'));
for(const k of ['knowledge','skills','understanding']){out+='<section class="reflection"><h3>'+k[0].toUpperCase()+k.slice(1)+'</h3><p>'+t(L.goals[k])+'</p>'+(after?'<div class="phase-compare">Starting point: '+t(L.before[s.before[k]]||T('Not recorded'))+'</div>':'')+'<fieldset><legend class="sr-only">'+k+' '+(after?'now':'starting point')+'</legend><div class="options">'+opts.map((v,i)=>'<label class="option"><input type="radio" data-reflect="'+(after?'after':'before')+'" data-id="'+k+'" name="'+(after?'after':'before')+'-'+k+'" value="'+i+'" '+(map[k]===i?'checked':'')+'><span>'+t(v)+'</span></label>').join('')+'</div></fieldset></section>';}
if(!after)out+=selectField('focus',T('My focus today','我今天的重点','오늘의 집중 영역'),[{value:'Recognising commands',label:T('Recognising commands','识别指令','명령 알아보기')},{value:'Tracing accurately',label:T('Tracing accurately','准确追踪','정확히 따라가기')},{value:'Explaining predictions',label:T('Explaining predictions','解释预测','예측 설명하기')}]);
else out+=selectField('evidence',T('My evidence of progress','我的进步证据','학습의 근거'),[{value:'A command check',label:T('A command check','指令检查题','명령 확인 문제')},{value:'My route trace',label:T('My route trace','我的路线追踪','나의 경로 추적')},{value:'My comparison explanation',label:T('My comparison explanation','我的比较解释','나의 비교 설명')},{value:'My checkpoint',label:T('My checkpoint','我的独立检查','나의 개별 점검')},{value:'I still need evidence or help',label:T('I still need evidence or help','我仍需要证据或帮助','아직 근거나 도움이 필요함')}])+field('reflectionNote',T('Optional: what did you notice?','选填：你注意到了什么？','선택: 무엇을 알게 되었나요?'),'textarea')+selectField('nextAction',T('My next action','我的下一步','나의 다음 행동'),[{value:'Check x before y',label:T('Check x before y','先检查 x，再检查 y','x부터 확인한 뒤 y 확인')},{value:'Track facing after every turn',label:T('Track facing after every turn','每次转向后追踪朝向','회전할 때마다 방향 확인')},{value:'Mark when the pen is up or down',label:T('Mark when the pen is up or down','标记提笔和落笔状态','펜을 올리고 내린 상태 표시')},{value:'Read each line in order',label:T('Read each line in order','按顺序逐行阅读','순서대로 한 줄씩 읽기')},{value:'Explain why two outputs differ',label:T('Explain why two outputs differ','解释两个输出为什么不同','두 결과가 다른 이유 설명')},{value:'Ask for a worked example',label:T('Ask for a worked example','请求示范例子','풀이 예시 요청')}])+'<p class="hint">Selecting “I need help” here is not an automatic message. Raise your hand or show your teacher.</p>';
return out;}
function subtabs(group,names){return '<nav class="subtabs" aria-label="'+group+' sections">'+names.map((v,i)=>'<button data-act="sub" data-group="'+group+'" data-index="'+i+'" class="'+(s.sub[group]===i?'active ':'')+(group==='main1'&&hasQ(main1Ids[i])?'done':'')+'">'+(i+1)+'. '+t(v)+'</button>').join('')+'</nav>';}
function subfooter(group,max){return '<div class="subfooter"><button data-act="sub-prev" data-group="'+group+'" '+(!s.sub[group]?'disabled':'')+'>← Previous part</button><span class="hint">'+(s.sub[group]+1)+' / '+max+'</span><button class="primary" data-act="sub-next" data-group="'+group+'">'+(s.sub[group]===max-1?'Finish this task →':'Next part →')+'</button></div>';}
function main1HTML(){const n=s.sub.main1;let out=subtabs('main1',[T('Syntax','语法','문법'),T('Movement','移动','이동'),T('Turns','转向','회전'),T('Pen','画笔','펜'),T('Comments','注释','주석'),T('Check','检查','확인')]);
if(n===0)out+=read(T('Syntax means the rules for writing code. A command needs its name, brackets and the right values. A parameter is an input a command accepts; 80 and 40 below are the supplied values.','语法是编写代码的规则。指令需要名称、括号和正确的值。参数是指令接收的输入；下方的 80 和 40 是提供的值。','문법은 코드를 쓰는 규칙입니다. 명령 이름, 괄호, 올바른 값이 필요합니다. 매개변수는 명령이 받는 입력이고, 아래의 80과 40은 넣어 준 값입니다.'))+codebox('t.goto(80, 40)')+'<div class="grid-three space"><div class="stat"><small>Command</small><strong>goto</strong></div><div class="stat"><small>Position</small><strong>x = 80, y = 40</strong></div><div class="stat"><small>Punctuation</small><strong>( &nbsp; , &nbsp; )</strong></div></div>'+question('syntax');
if(n===1)out+=read(T('goto(x, y) moves to a position. forward(distance) moves from the current position in the direction Turtle faces. goto does not change the facing direction.','goto(x, y) 移动到指定位置。forward(distance) 从当前位置沿朝向移动。goto 不改变朝向。','goto(x, y)는 지정한 위치로 이동합니다. forward(distance)는 현재 바라보는 방향으로 이동합니다. goto는 바라보는 방향을 바꾸지 않습니다.'))+codebox(L.examples.move.code)+question('move');
if(n===2)out+=read(T('right(90) turns clockwise; left(90) turns anticlockwise. A 90° turn is a quarter-turn. Turning changes the facing direction, not the position. A 180° turn faces the opposite way.','right(90) 顺时针转，left(90) 逆时针转。90° 是四分之一圈。转向只改变朝向，不改变位置。180° 后朝向相反。','right(90)은 시계 방향, left(90)은 반시계 방향 회전입니다. 90°는 4분의 1바퀴입니다. 회전하면 방향만 바뀌고 위치는 그대로입니다. 180°는 반대 방향입니다.'))+codebox(L.examples.turn.code)+question('turn');
if(n===3)out+=read(T('penup() lifts the pen; pendown() lowers it. Turtle can move in either state. Only movement with the pen down leaves a line.','penup() 提笔，pendown() 落笔。两种状态都能移动，但只有落笔移动才画线。','penup()은 펜을 올리고 pendown()은 내립니다. 두 상태 모두 이동하지만 펜이 내려가 있을 때만 선이 생깁니다.'))+codebox(L.examples.pen.code)+question('pen');
if(n===4)out+=read(T('A comment begins with # outside a string. It is a note for people reading the code, not a command. Explain the purpose of a section, not just “my code”.','在字符串外，注释以 # 开头。它是给读代码的人看的说明，不是指令。应解释代码段的目的，而不只是写“我的代码”。','문자열 밖에서 #로 시작하는 내용은 주석입니다. 코드를 읽는 사람을 위한 설명이지 명령이 아닙니다. 단순히 “내 코드”가 아니라 목적을 설명하세요.'))+codebox('# Move to the starting point without drawing\nt.penup()\nt.goto(-80, 0)\nt.pendown()')+question('comment');
if(n===5)out+=read(T('Pause and check. Point an arrow to the right. Turn it on the spot by 90° clockwise. Did its position change?','暂停检查。让箭头朝右，原地顺时针转 90°。位置有变化吗？','잠시 확인하세요. 화살표를 오른쪽으로 두고 제자리에서 시계 방향으로 90° 돌리세요. 위치가 바뀌었나요?'))+question('hinge');
return out+root.TurtleIDE.html(main1Ids[n])+subfooter('main1',6);}
function traceTable(){return '<div class="table-wrap"><table><thead><tr><th>Command</th><th>Position afterwards (x, y)</th><th>Direction of movement</th></tr></thead><tbody><tr><td><code>t.goto(0, -100)</code><small>Modelled first row</small></td><td>(0, -100)</td><td>Up</td></tr>'+[2,3].map((n,i)=>'<tr><td><code>'+['t.goto(0, 100)','t.goto(200, 100)'][i]+'</code></td><td><div class="xy"><input aria-label="Row '+n+' x-coordinate" inputmode="decimal" data-field="traceX'+n+'" value="'+E(s.fields['traceX'+n]||'')+'" placeholder="x" maxlength="12"><input aria-label="Row '+n+' y-coordinate" inputmode="decimal" data-field="traceY'+n+'" value="'+E(s.fields['traceY'+n]||'')+'" placeholder="y" maxlength="12"></div></td><td><select aria-label="Row '+n+' direction of movement" data-field="traceDir'+n+'"><option value="">Choose…</option>'+['Up','Down','Right','Left','Not sure'].map(v=>'<option '+(s.fields['traceDir'+n]===v?'selected':'')+'>'+v+'</option>').join('')+'</select></td></tr>').join('')+'</tbody></table></div>';}
function main2HTML(){let out=subtabs('main2',[T('Trace a route','追踪路线','경로 추적'),T('Compare','比较','비교'),T('Checkpoint','独立检查','개별 점검')]);const n=s.sub.main2;
if(n===0){out+=read(T('Return to the familiar route. Start at the Main Entrance (0, -200), facing right, with the pen down. Follow each instruction from the position you just reached. Record movement direction, not facing direction.','回到熟悉的路线。从正门 (0, -200) 开始，朝右，落笔。每次从上一步的位置继续。记录移动方向，而不是朝向。','익숙한 경로를 다시 봅시다. 정문 (0, -200)에서 오른쪽을 보고 펜을 내린 상태로 시작합니다. 방금 도착한 위치에서 계속하세요. 바라보는 방향이 아니라 이동 방향을 기록합니다.'))+statePanel(L.examples.route.start)+codebox(L.examples.route.code,s.steps.route)+traceTable()+field('traceExplain',T('Which line draws the final horizontal section towards C1? How do the coordinates show this?','哪一行画出通往 C1 的最后一段水平线？坐标如何说明？','어느 줄이 C1로 향하는 마지막 가로선을 그리나요? 좌표로 어떻게 알 수 있나요?'),'textarea','Line … because …')+spoken('traceSpoken')+'<div class="button-row"><button class="primary" data-act="check-route">Check my trace</button><button data-act="map">View Week 2 practice map</button></div>';
if(s.traceAttempts.length&&root.TurtleIDE.hasRun('route'))out+='<div class="feedback '+(s.traceAttempts.at(-1).correct?'good':'retry')+'"><strong>'+(s.traceAttempts.at(-1).correct?'Coordinates and movement directions checked.':'Compare your trace with each command. You can correct your response.')+'</strong><p>Line 2 ends at (0, 100), moving up. Line 3 ends at (200, 100), moving right. The y-value stays 100 in the last move.</p><small>Your first trace is kept separately.</small></div>';
if(s.traceAttempts.length&&!root.TurtleIDE.hasRun('route'))out+='<p class="notice">Trace prediction saved. Use the Python lab below to test it.</p>';
out+=root.TurtleIDE.html('route');
}
if(n===1){out+=read(T('Both programs begin at the same position and face the same way. The commands are similar, but their order changes. Predict both endpoints, then explain the difference.','两个程序起始位置和朝向相同。指令相似，但顺序变了。预测两个终点，再解释差异。','두 프로그램은 같은 위치와 방향에서 시작합니다. 명령은 비슷하지만 순서가 다릅니다. 두 끝점을 예측하고 차이를 설명하세요.'))+statePanel({x:0,y:0,h:0,pen:true})+'<div class="grid-two">'+['compareA','compareB'].map((id,i)=>'<div><h3>Program '+(i?'B':'A')+'</h3>'+codebox(L.examples[id].code,s.steps[id])+question(id)+'</div>').join('')+'</div>'+field('compareExplain',T('Why do the two drawings differ?','为什么两个图形不同？','두 그림이 다른 이유는 무엇인가요?'),'textarea','In Program A… In Program B…')+spoken('compareSpoken')+root.TurtleIDE.html('compareA')+root.TurtleIDE.html('compareB');}
if(n===2)out+=checkpointHTML();return out+subfooter('main2',3);}
function plotHTML(points,editable=false){const start={x:0,y:0,h:0,pen:false,segments:[]};let svg=M.svg(start,{minX:-80,maxX:80,minY:-60,maxY:60,step:20});svg=svg.replace(/<g transform="translate\([^]*?<\/g>/,'');svg=svg.replace(/aria-label="[^"]*"/,'aria-label="Your predicted visible line. '+(points.length?points.map((p,i)=>'Point '+(i+1)+': '+Number(p.x)+', '+Number(p.y)).join('; '):'No points selected yet.')+'"');const x=n=>40+(n+80)*2.5,y=n=>50+(60-n)*2.5;let add='';for(let i=1;i<points.length;i++)add+='<line x1="'+x(points[i-1].x)+'" y1="'+y(points[i-1].y)+'" x2="'+x(points[i].x)+'" y2="'+y(points[i].y)+'" stroke="#b27014" stroke-width="4"/>';
if(editable)for(let X=-80;X<=80;X+=20)for(let Y=-60;Y<=60;Y+=20)add+='<circle class="plot-point" cx="'+x(X)+'" cy="'+y(Y)+'" r="13" fill="transparent" tabindex="0" role="button" aria-label="Plot point '+X+', '+Y+'" data-act="plot-point" data-x="'+X+'" data-y="'+Y+'"/>';
points.forEach((p,i)=>{add+='<circle cx="'+x(p.x)+'" cy="'+y(p.y)+'" r="9" fill="#9f640e"/><text x="'+x(p.x)+'" y="'+(y(p.y)+4)+'" text-anchor="middle" fill="white" font-size="12" font-weight="bold">'+(i+1)+'</text>';});return '<div class="plot-wrap">'+svg.replace('</svg>',add+'</svg>')+'</div>';}
function readCheckpoint(){return {syntax:s.fields.cpSyntax||'',x:s.fields.cpX||'',y:s.fields.cpY||'',heading:s.fields.cpHeading||'',points:JSON.parse(JSON.stringify(s.checkpointDraft.points||[])),reason:s.fields.cpReason||'',comment:s.fields.cpComment||'',mode:s.fields.cpMode||'',support:s.support.filter(x=>x.stage==='main2'&&x.part===2),at:new Date().toISOString()};}
function checkpointHTML(){const cp=s.checkpoint;let out='<span class="tag amber">Individual evidence · 8 marks</span>'+read(T('Use a fresh program. Do not reveal the output or ask a partner for the answer. You may ask your teacher for help; record any support honestly. Your first submission is kept unchanged.','使用新程序，不显示结果，不向同伴索要答案。可以向老师求助，但要如实记录。第一次提交会原样保留。','새 프로그램입니다. 결과를 보거나 짝에게 답을 묻지 마세요. 선생님께 도움을 받을 수 있지만 받은 도움을 솔직하게 기록하세요. 첫 제출은 그대로 보관됩니다.'))+statePanel(L.examples.checkpoint.start)+codebox(L.examples.checkpoint.code);
if(cp){out+='<div class="notice"><strong>First checkpoint saved.</strong><p>Your original prediction is unchanged. You can now test the code below, then keep a correction separately. Your teacher reviews the first submission as independent evidence.</p><small>'+E(new Date(cp.at).toLocaleString())+' · '+E(cp.mode||'Support not stated')+'</small></div><div class="grid-two"><div class="panel"><h3>Your recorded prediction</h3><p>Syntax correction: <code>'+E(cp.syntax||'Not answered')+'</code></p><p>Final position: ('+E(cp.x||'?')+', '+E(cp.y||'?')+')</p><p>Facing: '+E(cp.heading||'Not answered')+'</p><p>'+E(cp.reason||'No explanation recorded')+'</p><pre>'+E(cp.comment||'No comment recorded')+'</pre></div><div>'+plotHTML(cp.points,false)+'<p class="hint">Your predicted visible line, not a model answer.</p></div></div><details><summary>Record a later correction or explanation</summary>'+field('cpCorrection',T('What would you change, and why?','你会修改什么？为什么？','무엇을 바꾸고 싶나요? 왜인가요?'),'textarea')+'<button data-act="save-correction">Keep correction separately</button>'+s.checkpointCorrections.map(c=>'<p class="notice">'+E(c.text)+'</p>').join('')+'</details>';return out+root.TurtleIDE.html('checkpoint');}
out+='<div class="checkpoint-form">'+field('cpSyntax',T('1. Fix this line: t.goto(60 20) [1 mark]','1. 修正这一行：t.goto(60 20)【1 分】','1. t.goto(60 20)을 고치세요. [1점]'),'text','Write the corrected command')+'<fieldset><legend>'+t(T('2. Where does the program above finish? [2 marks]','2. 上方程序最终在哪里？【2 分】','2. 위 프로그램의 마지막 위치는? [2점]'))+'</legend><div class="grid-two">'+field('cpX',T('Final x-coordinate','最终 x 坐标','마지막 x 좌표'),'text','x')+field('cpY',T('Final y-coordinate','最终 y 坐标','마지막 y 좌표'),'text','y')+'</div></fieldset>'+selectField('cpHeading',T('3. Which way does it face at the end? [1 mark]','3. 最终朝向哪里？【1 分】','3. 마지막에 어느 방향을 보나요? [1점]'),['Right','Up','Left','Down','Not sure'])+'<fieldset><legend>'+t(T('4. Plot the two visible line segments. Select three points in order. [2 marks]','4. 标出两段看得见的线，按顺序选三个点。【2 分】','4. 보이는 선분 두 개를 그리세요. 순서대로 세 점을 고르세요. [2점]'))+'</legend><p class="hint">'+t(T('Select the start of the first visible line, its corner, then the finish. You can tap the grid or use the coordinate boxes below.','选择第一段可见线的起点、转角、终点。可以点击网格，也可以使用下方坐标框。','첫 선의 시작점, 모서리, 끝점을 고르세요. 격자를 누르거나 아래 좌표 입력란을 사용할 수 있습니다.'))+'</p>'+plotHTML(s.checkpointDraft.points,true)+'<p>'+s.checkpointDraft.points.map((p,i)=>(i+1)+': ('+p.x+', '+p.y+')').join(' → ')+'</p><div class="grid-two">'+selectField('plotX',T('Point x','点的 x','점의 x'),['-80','-60','-40','-20','0','20','40','60','80'])+selectField('plotY',T('Point y','点的 y','점의 y'),['-60','-40','-20','0','20','40','60'])+'</div><div class="button-row"><button data-act="add-point">Add this point</button><button data-act="undo-point">Undo point</button><button data-act="clear-points">Clear plot</button></div></fieldset>'+field('cpReason',T('5. Why does moving to (-40, 20) leave no line? [1 mark]','5. 为什么移动到 (-40, 20) 时不画线？【1 分】','5. (-40, 20)으로 이동할 때 왜 선이 생기지 않나요? [1점]'),'textarea')+field('cpComment',T('6. Write one meaningful Python comment for a section of this program. [1 mark]','6. 为程序的某一段写一条有意义的 Python 注释。【1 分】','6. 프로그램의 한 부분에 알맞은 Python 주석을 쓰세요. [1점]'),'textarea','# ...')+selectField('cpMode',T('How did you complete this checkpoint?','你如何完成本次检查？','이번 점검은 어떻게 풀었나요?'),[{value:'Independent (student report)',label:T('Independently','独立完成','혼자 풀었음')},{value:'With teacher / reference help',label:T('With teacher or reference help','借助老师或参考资料','선생님 또는 참고 자료의 도움을 받음')},{value:'Unfinished — I need help',label:T('I could not finish; I need help','未能完成，需要帮助','완성하지 못해 도움이 필요함')}])+'<button class="primary" data-act="submit-checkpoint">Save my first checkpoint</button><p class="hint space">Saving unlocks Python testing below. A later test or correction cannot replace your first version.</p></div>';return out+root.TurtleIDE.html('checkpoint');}
function extensionHTML(){return '<span class="tag">Optional · No extra upload</span>'+read(T('Choose one challenge, or continue to your Learning pitstop. This workspace is separate from your checkpoint. Start with the commands from today; extra Python features are optional.','选择一个挑战，或继续学习加油站。这个工作区独立于检查题，先使用今天的指令；其他 Python 功能为选做。','도전 하나를 고르거나 학습 점검으로 넘어가세요. 이 작업 공간은 개별 점검과 별개입니다. 오늘 배운 명령부터 시작하세요. 추가 Python 기능은 선택입니다.'))+selectField('extensionChoice',T('My challenge','我的挑战','나의 도전'),[{value:'Same drawing',label:T('Same drawing, different commands','同一图形，不同指令','같은 그림, 다른 명령')},{value:'Invisible difference',label:T('Same line, different facing direction','线相同，朝向不同','같은 선, 다른 방향')},{value:'Partner prediction',label:T('Make a partner prediction challenge','设计同伴预测题','짝을 위한 예측 문제 만들기')}])+'<div class="panel"><h3>1 · Same drawing</h3><p>Use <code>goto()</code> to draw Program A’s L-shaped path: right 80, then down 40.</p><h3>2 · Invisible difference</h3><p>Compare <code>t.forward(40)</code> with <code>t.forward(40)</code> followed by <code>t.left(90)</code>. What changes if both then run <code>t.forward(40)</code>?</p><h3>3 · Partner prediction</h3><p>Write three to five commands with a turn or a pen change. State the starting position, heading and pen state.</p></div>'+root.TurtleIDE.html('extension')+field('extensionExplain',T('Explain what you tried and what you noticed.','解释你尝试了什么，以及发现了什么。','무엇을 시도했고 무엇을 알게 되었나요?'),'textarea');}
function canCheckGuide(i){return s.teacher||G.steps.slice(0,i).every(v=>s.guideChecks[v.id]);}
function submitHTML(){const i=s.guideStep,step=G.steps[i],missing=missingCore();let out='<div class="notice"><strong>'+t(T('One report. Four actions.','一份报告，四个动作。','보고서 한 개, 네 가지 행동.'))+'</strong><div class="routine space"><span>Save</span>→<span>Find</span>→<span>Attach</span>→<span>Turn in</span></div></div>';
if(missing.length)out+='<div class="notice warning"><strong>Core evidence still missing: </strong>'+missing.map(x=>E(x.name.en)).join(', ')+'. '+(s.teacher?'Teacher preview may prepare an incomplete report.':s.teacherRelease?'Your teacher has released incomplete evidence; missing work stays visible in the report.':'Return to the lesson or ask your teacher before exporting.')+'</div>';
out+='<div class="row between"><span class="tag">'+E(G.routeLabel(s))+'</span><button class="small" data-act="profile">Change my device</button></div><p class="hint space">'+t(T('Follow one step at a time. Tick a step only after doing it. These ticks are your own confirmations, not checks made by Teams.','逐步操作，完成后才勾选。这些是你自己的确认，不是 Teams 自动验证。','한 단계씩 따라 하고 완료한 뒤 체크하세요. 체크 표시는 자신의 확인이며 Teams가 확인한 것이 아닙니다.'))+'</p><div class="guide-tabs" role="navigation" aria-label="Submission steps">'+G.steps.map((x,j)=>'<button data-act="guide-step" data-index="'+j+'" class="'+(j===i?'active ':'')+(s.guideChecks[x.id]?'done':'')+'" aria-label="'+(j+1)+'. '+E(x.title.en)+'">'+(j+1)+'</button>').join('')+'</div><div class="eyebrow">Step '+(i+1)+' of 9</div><h2 class="guide-step-title">'+t(step.title)+'</h2><p class="guide-instruction">'+t(step.instruction)+'</p><p>'+t(G.deviceText(s,i))+'</p><div class="guide-file">'+E(G.filename(s))+'</div>';
if(i===0)out+='<div class="button-row"><button data-act="preview-report">Preview my report</button></div>';
if(i===1)out+='<div class="button-row"><button class="primary" data-act="prepare-pdf" '+(missing.length&&!s.teacher&&!s.teacherRelease?'disabled':'')+'>Prepare PDF</button><button data-act="save-pdf" '+(!pdf?'disabled':'')+'>'+(['ipad','android'].includes(s.device)?'Save / share PDF':'Download PDF')+'</button>'+(pdf?'<button data-act="download-pdf">Download PDF instead</button><button data-act="open-pdf">Open PDF</button>':'')+'</div><p class="hint">'+(pdf?'PDF prepared. Saving still needs your confirmation.':s.pdfPreparedAt?'A PDF was prepared earlier. Prepare again if you need another copy.':'Prepare the report before saving it.')+'</p>';
if(i===2)out+=field('folder',T('My PDF is saved in…','我的 PDF 保存在……','PDF를 저장한 위치는…'),'text',s.device==='ipad'?'For example: On My iPad / Downloads':'For example: Downloads');
if(i===4)out+='<div class="notice"><strong>Assignment to find:</strong><p>'+E(config.assignmentTitle)+'</p>'+(config.teamsUrl?'<a class="button primary" href="'+E(config.teamsUrl)+'" target="_blank" rel="noopener noreferrer">Open Teams assignment ↗</a>':'<p class="hint">Open your school Teams app or browser. Your teacher can add a direct link in Teacher tools.</p>')+'</div>';
out+=G.render(s,i,config,t)+'<div class="guide-result"><strong>'+t(T('What you should see','你应该看到','확인할 내용'))+'</strong><p>'+t(step.result)+'</p></div><div class="guide-check">'+(!canCheckGuide(i)?'<p class="hint">Confirm the earlier steps first. You may still read this step.</p>':'')+'<label class="checkrow"><input type="checkbox" data-guide-check="'+step.id+'" '+(s.guideChecks[step.id]?'checked':'')+' '+(!canCheckGuide(i)?'disabled':'')+'><span>'+t(step.check)+'</span></label></div><div class="row between"><button data-act="guide-prev" '+(i===0?'disabled':'')+'>← Previous step</button><button class="primary" data-act="guide-next">'+(i===8?'Finish submission guide →':'Next step →')+'</button></div><details class="rule"><summary>My screen looks different / I am stuck</summary><div class="help-list">'+[['device','My screen looks different'],['missing','I cannot find the PDF'],['duplicates','I see several similar PDFs'],['assignment','I cannot find the assignment'],['attached','I attached it. Am I finished?'],['failed','Something failed']].map(([v,l])=>'<button data-act="guide-help" data-id="'+v+'">'+l+'</button>').join('')+'</div></details>';
return out;}
function challengeHTML(){if(!s.guideChecks.confirm&&!s.teacher)return '<div class="locked">Complete the submission guide first. Check that Teams shows your work as turned in.</div>';let out='<span class="tag">15 unique questions · Optional practice</span>'+read(T('Practise Python Turtle while others finish. Read carefully and predict before choosing. You do not need to upload anything else. Stop when your teacher gives the closing instruction.','在其他同学完成时练习 Python Turtle。认真阅读，先预测再选择，不需要再上传任何文件。老师发出结束指令时停止。','다른 학생들이 마무리하는 동안 Python Turtle을 연습하세요. 답을 고르기 전에 예측하세요. 추가 파일 제출은 없습니다. 선생님이 마치라고 하면 멈추세요.'));
if(config.gimkitUrl)out+='<div class="panel"><h2>Ready for Gimkit?</h2><p>The activity opens in a new tab. Your lesson remains saved here.</p><a class="button primary" data-external="gimkit" href="'+E(config.gimkitUrl)+'" target="_blank" rel="noopener noreferrer">Open Gimkit ↗</a><p class="hint space">This is a question bank, not necessarily a fixed test out of 15. Gameplay may repeat questions.</p></div>';
else out+='<div class="notice warning"><strong>The Gimkit link has not been added yet.</strong><p>Your teacher can add it in Teacher tools. The same 15-question bank is available as backup practice below.</p></div>';
out+='<details '+(!config.gimkitUrl?'open':'')+'><summary>Backup practice here — not Gimkit</summary><p class="hint">Use this only when Gimkit is not available. No game account, no extra submission and no result sent to Teams.</p>'+quizHTML()+'</details>';return out;}
function quizHTML(){const q=root.TurtleQuiz[quizIndex],a=s.quiz.answers[q.id],last=s.quiz.history.filter(h=>h.id===q.id).at(-1);return '<div class="quiz-progress" aria-label="Practice progress">'+root.TurtleQuiz.map(x=>'<span class="'+(s.quiz.history.some(a=>a.id===x.id)?'done':'')+'"></span>').join('')+'</div><p class="eyebrow space">Question '+(quizIndex+1)+' / 15</p><div class="question"><fieldset><legend>'+t(q.stem)+'</legend>'+(q.code?codebox(q.code):'')+'<div class="options">'+q.options.map((o,j)=>'<label class="option"><input type="radio" data-quiz="'+q.id+'" name="practice" value="'+j+'" '+(a===j?'checked':'')+'><span>'+t(o)+'</span></label>').join('')+'</div></fieldset><div class="button-row"><button data-act="check-practice">Check answer</button></div>'+(last&&last.value===a?'<div class="feedback '+(a===q.correct?'good':'retry')+'"><strong>'+(a===q.correct?'Correct.':'Try a correction.')+'</strong><p>'+t(q.why)+'</p></div>':'')+'</div><div class="row between"><button data-act="quiz-prev" '+(quizIndex===0?'disabled':'')+'>← Previous</button><span class="hint">'+new Set(s.quiz.history.map(x=>x.id)).size+' unique questions attempted</span><button data-act="quiz-next">'+(quizIndex===14?'Review progress':'Next →')+'</button></div>';}
function modal(title,html,cls=''){const old=document.getElementById('dialog');if(old)old.remove();const d=document.createElement('dialog');d.id='dialog';d.className=cls;d.innerHTML='<div class="modal-head"><h2>'+E(title)+'</h2><button data-act="close-modal" aria-label="Close dialog">Close ✕</button></div><div class="modal-body">'+html+'</div>';document.getElementById('modals').append(d);d.addEventListener('close',()=>d.remove());d.showModal();root.ScreenFit?.mountDialog(d);return d;}
function closeModal(){document.getElementById('dialog')?.close();}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),120000);}
function coreSupport(text){const stage=L.stages[s.stage].id;s.support.push({stage,part:s.sub.main2,text,at:new Date().toISOString()});touch(!['submit','challenge'].includes(stage));}
function gotoStage(n){if(n<0||n>=L.stages.length)return;if(!s.teacher&&n>s.stage){if(n===9&&!s.guideChecks.confirm){toast('Check that Teams shows your work as turned in first.');return;}const blocking=L.stages.slice(0,n).filter(x=>!['extension','challenge'].includes(x.id)&&!complete(x.id));if(blocking.length&&!s.teacherRelease){toast('Finish '+blocking[0].name.en+' first, or ask your teacher for help.');return;}}s.stage=n;render();document.getElementById('main').focus();window.scrollTo({top:0,behavior:'smooth'});}
function canSub(group,index){if(s.teacher||s.teacherRelease||index<=(s.sub[group]||0))return true;if(group==='main1')return main1Ids.slice(0,index).every(hasQ);if(index>0&&!s.traceAttempts.length)return false;if(index>1&&(!hasQ('compareA')||!hasQ('compareB')||!(s.fields.compareExplain||s.fields.compareSpoken)))return false;return true;}
function profileModal(){modal('Your lesson profile','<form id="profile-form"><p class="hint">Changing device changes the guide, not the Python content. Changing name or class requires a new PDF.</p><div class="grid-two"><div class="field"><label for="p-name">Name</label><input id="p-name" value="'+E(s.name)+'" maxlength="60" required></div><div class="field"><label for="p-class">Class</label><input id="p-class" value="'+E(s.klass)+'" maxlength="30" required></div></div><div class="field"><label for="p-device">Device</label><select id="p-device">'+deviceOptions(s.device)+'</select></div><div class="grid-two"><div class="field"><label for="p-browser">Browser</label><select id="p-browser">'+browserOptions(s.device,s.browser)+'</select></div><div class="field"><label for="p-teams">Teams route</label><select id="p-teams"><option value="app" '+(s.teamsMode==='app'?'selected':'')+'>Teams app</option><option value="browser" '+(s.teamsMode==='browser'?'selected':'')+'>Teams browser</option></select></div></div><button class="primary" type="submit">Save profile</button></form><div class="rule"><p class="hint">Shared device? Export your evidence before ending the session.</p><button data-act="teacher-assist">Teacher: release incomplete evidence</button><button data-act="end-session">End session / clear this student’s work</button></div>');}
const sources=[['Python Turtle command behaviour','https://docs.python.org/3/library/turtle.html'],['Python comments','https://docs.python.org/3/reference/lexical_analysis.html'],['Microsoft: turn in an assignment','https://support.microsoft.com/en-us/education/assignments/turn-in-an-assignment-in-microsoft-teams'],['Microsoft: mobile assignments','https://support.microsoft.com/en-us/education/assignments/manage-assignments-on-a-mobile-device'],['Apple: save a PDF in Safari','https://support.apple.com/en-my/guide/ipad/ipade2917f90/ipados'],['Google: Chrome downloads','https://support.google.com/chrome/answer/95759'],['Gimkit: CSV import','https://help.gimkit.com/en/article/create-a-kit-with-a-csv-file-wv72i9/'],['Gimkit: assignments','https://help.gimkit.com/en/article/assignments-explained-1dgudm/'],['Gimkit: practice','https://help.gimkit.com/en/article/practice-mode-1vyyl7l/']];
function sourcesHTML(){return '<p>Aligned to your Year 7 Term 1 Week 3 scheme and the Week 2 route context. Command behaviour follows standard Python Turtle.</p><h3>Privacy and limits</h3><p>Student answers are stored in this browser, not a server. The PDF is created on the device. The app cannot see Files, verify a saved copy, read Teams, confirm a submission or publish a Gimkit kit. External sites need the school account and internet access. Browser storage can be cleared by private browsing, device policies or the user.</p><p>Submission pictures are labelled illustrations unless your teacher has added genuine screenshots. Interfaces vary by device and school settings. Teacher mode is not authentication; do not use this app as a secure examination system.</p><h3>Official references</h3>'+sources.map(([l,u])=>'<p><a href="'+E(u)+'" target="_blank" rel="noopener noreferrer">'+E(l)+' ↗</a></p>').join('');}
function referenceModal(){if(L.stages[s.stage].id==='main2'&&s.sub.main2===2&&!s.checkpoint)coreSupport('Opened command reference during checkpoint');modal('Command guide','<p>'+t(T('Read a command as an exact instruction. Coordinates name a destination; forward movement uses the current heading.','把指令看作精确的操作。坐标表示目标位置，前进方向由当前朝向决定。','명령을 정확한 지시로 읽으세요. 좌표는 목적지이며 앞으로 이동할 때는 현재 방향을 따릅니다.'))+'</p><div class="table-wrap"><table><thead><tr><th>Command</th><th>What happens</th></tr></thead><tbody>'+[['t.goto(x, y)','Go to the position (x, y). Heading stays the same.'],['t.forward(distance)','Move forwards in the direction the Turtle faces.'],['t.right(angle)','Turn clockwise on the spot.'],['t.left(angle)','Turn anticlockwise on the spot.'],['t.penup()','Move without drawing.'],['t.pendown()','Following movements draw a line.'],['# comment','Leave an explanation for people, not a Turtle command.']].map(([c,d])=>'<tr><td><code>'+E(c)+'</code></td><td>'+E(d)+'</td></tr>').join('')+'</tbody></table></div><h3>Keywords</h3>'+L.terms.map(a=>'<p><strong>'+E(a[0])+'</strong> · '+E(s.lang==='zh'?a[1]:s.lang==='ko'?a[2]:'')+'<br>'+E(a[3])+'</p>').join(''));}
function helpModal(id){const help={device:['My screen looks different','Check your device, browser and whether Teams is an app or a browser tab. Button positions vary. Do not close your lesson. Use Change my device to choose the matching route.'],missing:['Find the PDF','On iPad, open Files and look in the folder you chose when saving. On Android, check Chrome Downloads or your Files app. On a laptop, open the browser download list, then show the file in its folder. If the PDF was only opened, return to Save your PDF and save a copy.'],duplicates:['Choose the correct report','Match your name, class and Week 3 lesson title. Open the report and check your latest answers. A duplicate may have (1) in its filename. Attach the correct version; do not guess from the file icon.'],assignment:['Find the assignment','Check that you are signed into your school account and the correct class. Find: '+config.assignmentTitle+'. If it is missing or closed, raise your hand and show your teacher. Do not post your work into another class or a chat.'],attached:['One more action','An attachment is not a submitted assignment. Select Turn in, then check for the Turned in status and its submission date/time. This app cannot verify that for you.'],failed:['Keep your evidence safe','Keep this lesson tab and any saved PDF open. Do not refresh, clear storage or delete files. Raise your hand and show the exact message to your teacher. You can prepare another PDF from the same saved answers after the issue is resolved.']};const [title,msg]=help[id]||help.device;modal(title,'<p>'+E(msg)+'</p><p class="guide-file">'+E(G.filename(s))+'</p><div class="button-row"><button data-act="profile">Change my device</button><button data-act="support">I need teacher help</button></div>');}
function shotRoute(){return {device:document.getElementById('shot-device')?.value||s.device,browser:document.getElementById('shot-browser')?.value||s.browser,teamsMode:document.getElementById('shot-teams')?.value||s.teamsMode};}
function shotIdx(){return Number(document.getElementById('shot-step')?.value||0);}
function updateShotPreview(){const el=document.getElementById('shot-preview');if(!el)return;const key=G.screenshotKey(shotRoute(),shotIdx()),v=config.screenshotOverrides[key];el.innerHTML=v?'<p class="hint">Tap the screenshot to place its numbered highlight. It is saved automatically on this teacher browser.</p><img id="shot-marker-image" src="'+E(v.src)+'" alt="Teacher supplied screenshot. Tap to mark the relevant control." style="width:100%;max-height:440px;object-fit:contain;cursor:crosshair"><p>'+E(v.caption||'Teacher screenshot')+(v.point?' · Highlight set':'')+'</p>':'<p class="notice">This route currently uses the labelled illustration. Choose an image to replace this step.</p>';}
function teacherModal(){if(!s.teacher)return;modal('Teacher tools','<div class="notice"><strong>Classroom review — not secure login.</strong><p>Settings below are local to this browser. Export <code>config.js</code> and replace the deployed file to apply them to students. Student answers are never included in that file.</p></div><div class="teacher-grid"><section><h3>Lesson destinations</h3><form id="config-form"><div class="field"><label for="cfg-title">Teams assignment title</label><input id="cfg-title" maxlength="150" value="'+E(config.assignmentTitle)+'" required></div><div class="field"><label for="cfg-teams">Teams assignment URL (optional, https)</label><input id="cfg-teams" type="url" value="'+E(config.teamsUrl)+'" placeholder="https://teams.microsoft.com/..."></div><div class="field"><label for="cfg-gimkit">Gimkit Assignment or Practice URL</label><input id="cfg-gimkit" type="url" value="'+E(config.gimkitUrl)+'" placeholder="https://www.gimkit.com/..."></div><button class="primary" type="submit">Save settings on this device</button></form><div class="button-row"><button data-act="export-config">Export config.js</button><button data-act="share-setup">Create configured student link</button></div><p class="hint">The configured link carries the title and destination links only. Screenshot replacements require config.js deployment. Use a Practice or Assignment link, not a kit page showing answers.</p><a href="teacher/Turtle_Trace_Gimkit_Template1.csv" download>Download the 15-question Gimkit CSV</a><p><a href="teacher/SETUP.html" target="_blank" rel="noopener">Setup notes and answer key ↗</a></p><div class="button-row"><button data-act="answer-key">Lesson answer key</button><button data-act="project-guide">Project submission overview</button></div></section><section><h3>Replace a guide picture</h3><p class="hint">Use a student-view test account. Crop or blur names, emails, notifications and unrelated files before uploading. PNG / JPEG / WebP only; maximum 12 MB.</p><div class="grid-two"><div class="field"><label for="shot-device">Device</label><select id="shot-device">'+deviceOptions(s.device)+'</select></div><div class="field"><label for="shot-browser">Browser</label><select id="shot-browser">'+browserOptions(s.device,s.browser)+'</select></div></div><div class="grid-two"><div class="field"><label for="shot-teams">Teams route</label><select id="shot-teams"><option value="app" '+(s.teamsMode==='app'?'selected':'')+'>Teams app</option><option value="browser" '+(s.teamsMode==='browser'?'selected':'')+'>Teams browser</option></select></div><div class="field"><label for="shot-step">Guide step</label><select id="shot-step">'+G.steps.map((x,i)=>'<option value="'+i+'">'+(i+1)+'. '+E(x.title.en)+'</option>').join('')+'</select></div></div><div class="field"><label for="shot-file">Choose your screenshot</label><input id="shot-file" type="file" accept="image/png,image/jpeg,image/webp"></div><div class="field"><label for="shot-caption">Caption / version note</label><input id="shot-caption" maxlength="200" placeholder="For example: School iPad, Safari, checked September 2026"></div><button data-act="remove-shot">Restore illustration for this step</button><div id="shot-preview" class="space"></div></section></div>','teacher-modal');updateShotPreview();}
function persistConfig(){try{localStorage.setItem(CKey,JSON.stringify(config));return true;}catch(e){toast('Browser storage is full. Export config.js now to keep these screenshot settings.');return false;}}
async function uploadShot(file){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>12*1024*1024){toast('Choose PNG, JPEG or WebP below 12 MB.');return;}const key=G.screenshotKey(shotRoute(),shotIdx()),caption=document.getElementById('shot-caption').value||'Teacher supplied student-view screenshot';const u=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=u;});const scale=Math.min(1,1400/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);config.screenshotOverrides[key]={src:canvas.toDataURL('image/jpeg',.86),caption,point:null};persistConfig();updateShotPreview();toast('Screenshot added to this route. Export config.js to share it with students.');}catch(e){toast('The image could not be opened. Try a PNG or JPEG.');}finally{URL.revokeObjectURL(u);}}
function answerKey(){modal('Teacher answer key','<p class="hint">This static app is a learning tool, not a secure assessment platform. Give feedback after the individual checkpoint.</p>'+Object.entries(L.questions).map(([k,q])=>'<div class="review-key"><strong>'+E(k)+': '+E(q.options[q.correct].en)+'</strong><p>'+E(q.why.en)+'</p></div>').join('')+'<h3>Route trace</h3><p>Line 2: (0, 100), Up. Line 3: (200, 100), Right. The final segment is horizontal because y remains 100 while x changes.</p><h3>Independent checkpoint · 8 marks</h3><p>1. <code>t.goto(60, 20)</code> [1]<br>2. x = 40 [1], y = -20 [1]<br>3. Down [1]<br>4. (-40, 20) → (40, 20) [1], then (40, 20) → (40, -20) [1]<br>5. The pen is up during the first move [1].<br>6. A relevant comment beginning with # explaining the purpose of a section [1]. Accept alternative accurate wording.</p>'+M.svg(M.trace(L.examples.checkpoint.code).at(-1))+'<p>Interpret unsupported coordinates as evidence of the specific misconception, not a typing-speed score. Reference access and self-reported assistance are shown separately.</p><h3>Gimkit / backup answers</h3>'+root.TurtleQuiz.map((q,i)=>'<p><strong>'+(i+1)+'. '+E(q.options[q.correct].en)+'</strong><br>'+E(q.why.en)+'</p>').join(''));}
function projectGuide(){modal('Save → Find → Attach → Turn in','<p class="notice">Projection reference. The pictures below are labelled illustrations unless replaced by teacher screenshots. Students follow their own device guide.</p><div class="overview">'+[1,3,5,8].map(i=>'<section class="panel"><h3>'+(i===1?'1 · Save':i===3?'2 · Find':i===5?'3 · Attach':'4 · Turn in and check')+'</h3><p>'+E(G.steps[i].instruction.en)+'</p>'+G.render(s,i,config,t)+'</section>').join('')+'</div>','print-guide');}
function addPoint(x,y){if(s.checkpoint)return;if(!Number.isFinite(x)||!Number.isFinite(y)||x<-80||x>80||y<-60||y>60||x%20||y%20){toast('Choose a labelled grid point: x -80 to 80, y -60 to 60, in steps of 20.');return;}if(s.checkpointDraft.points.length>=3){toast('Three points selected. Undo a point to change your prediction.');return;}s.checkpointDraft.points.push({x,y});touch();render();document.querySelector('.plot-wrap')?.scrollIntoView({block:'center'});}
function preparePDF(){if(missingCore().length&&!s.teacher&&!s.teacherRelease){toast('Complete the core stages before preparing your report.');return Promise.resolve();}return root.EvidenceReport.prepare(s).then(out=>{pdf=out;s.pdfPreparedAt=out.at;s.pdfVersion=out.version;save();render();toast('PDF prepared. Now save a copy, then confirm it in the guide.');}).catch(err=>{console.error(err);toast('PDF preparation failed. Keep the tab open. Try again, or use Preview report → Print / Save PDF.');});}
async function savePDF(){if(!pdf){toast('Prepare your PDF first.');return;}const file=new File([pdf.blob],pdf.filename,{type:'application/pdf'});if(['ipad','android'].includes(s.device)&&navigator.canShare&&navigator.canShare({files:[file]})){try{await navigator.share({files:[file],title:'My Turtle Trace report'});toast('Check the folder where you saved the PDF before confirming the step.');}catch(e){if(e.name!=='AbortError'){download(pdf.blob,pdf.filename);toast('Sharing was unavailable. A download was requested instead.');}}}else{download(pdf.blob,pdf.filename);toast('A download was requested. Check that the PDF has saved before ticking the step.');}}
function previewReport(){const result=root.EvidenceReport.preview(s);modal('Preview your evidence','<div class="button-row"><button data-act="print-report">Print / Save PDF fallback</button></div><p class="hint">This is a preview, not proof that a file has been saved. Use Prepare PDF in the guide for the named report.</p><div class="report-preview-scroll">'+result.html+'</div>','report-modal');s.reportPreviewed=true;save();}
function quizResult(){const history=s.quiz.history,ids=new Set(history.map(x=>x.id));let first=0;for(const q of root.TurtleQuiz){const a=history.find(h=>h.id===q.id);if(a?.value===q.correct)first++;}modal('Backup practice progress','<p><strong>'+ids.size+' / 15 unique questions attempted.</strong></p><p>'+first+' first answers correct out of the '+ids.size+' attempted. This is local backup practice, not a Gimkit score, and it is not sent to Teams.</p><p>Revisit questions you found difficult. Stop when your teacher gives the closing instruction.</p>');}
document.addEventListener('submit',ev=>{const f=ev.target;if(f.id==='entry'){ev.preventDefault();const d=Object.fromEntries(new FormData(f)),teacher=d.name.trim().toLowerCase()==='teacher';if(!teacher&&(!d.klass.trim()||!d.device)){document.getElementById('entry-error').textContent='Enter your class and choose your device.';return;}if(load(KEY)?.name&&!confirm('Start a new lesson on this browser? This replaces the previous student’s local work. Save their PDF first.'))return;d.name=d.name.trim();d.klass=d.klass.trim()||(teacher?'Teacher review':'');d.device=d.device||'windows';s=fresh(d);pdf=null;render();return;}
if(f.id==='profile-form'){ev.preventDefault();const name=document.getElementById('p-name').value.trim(),klass=document.getElementById('p-class').value.trim(),device=document.getElementById('p-device').value;if(!name||!klass||!device){toast('Enter name, class and device.');return;}const identityChanged=name!==s.name||klass!==s.klass;s.name=name;s.klass=klass;s.device=device;s.browser=document.getElementById('p-browser').value;s.teamsMode=document.getElementById('p-teams').value;touch(identityChanged);closeModal();render();return;}
if(f.id==='config-form'){ev.preventDefault();if(!s.teacher)return;const title=document.getElementById('cfg-title').value.trim(),teams=document.getElementById('cfg-teams').value.trim(),gimkit=document.getElementById('cfg-gimkit').value.trim();if(!validURL(teams,'teamsUrl')||!validURL(gimkit,'gimkitUrl')){toast('Use HTTPS links on Microsoft / Office domains for Teams, and gimkit.com for Gimkit.');return;}config=cleanConfig({...config,assignmentTitle:title,teamsUrl:teams,gimkitUrl:gimkit});persistConfig();toast('Settings saved locally. Export config.js or a configured student link before sharing.');return;}});
function recordInput(el){if(!s)return;if(el.dataset.field){s.fields[el.dataset.field]=el.type==='checkbox'?el.checked:el.value;touch(!['folder','plotX','plotY'].includes(el.dataset.field));}if(el.dataset.special){s[el.dataset.special]=el.value;touch();}if(el.dataset.q){const q=s.q[el.dataset.q]||(s.q[el.dataset.q]={history:[]});q.value=Number(el.value);touch();document.querySelector('#q-'+el.dataset.q+' .feedback')?.remove();}if(el.dataset.reflect){s[el.dataset.reflect][el.dataset.id]=Number(el.value);touch();}if(el.dataset.quiz){s.quiz.answers[el.dataset.quiz]=Number(el.value);touch(false);document.querySelector('#main .feedback')?.remove();}}
document.addEventListener('input',ev=>{if(ev.target.id==='shot-caption'&&s?.teacher){const k=G.screenshotKey(shotRoute(),shotIdx());if(config.screenshotOverrides[k]){config.screenshotOverrides[k].caption=ev.target.value;persistConfig();}return;}if(['INPUT','TEXTAREA'].includes(ev.target.tagName)&&!['checkbox','radio','file'].includes(ev.target.type))recordInput(ev.target);});
document.addEventListener('change',ev=>{const el=ev.target;if(el.id==='entry-device'){document.getElementById('entry-browser').innerHTML=browserOptions(el.value,'');document.getElementById('entry-teams').value=['ipad','android'].includes(el.value)?'app':'browser';return;}if(el.id==='p-device'){document.getElementById('p-browser').innerHTML=browserOptions(el.value,'');return;}if(el.id==='shot-device'){document.getElementById('shot-browser').innerHTML=browserOptions(el.value,'');updateShotPreview();return;}if(['shot-browser','shot-teams','shot-step'].includes(el.id)){updateShotPreview();return;}if(el.id==='shot-file'){uploadShot(el.files[0]);return;}if(!s)return;if(el.id==='lang'){s.lang=el.value;touch(false);render();return;}if(el.dataset.guideCheck){const key=el.dataset.guideCheck,i=G.steps.findIndex(x=>x.id===key);if(!canCheckGuide(i)){el.checked=false;toast('Confirm earlier steps first.');return;}if(el.checked&&key==='report'&&!s.reportPreviewed){el.checked=false;toast('Open Preview my report and check your name, class and answers first.');return;}if(el.checked&&key==='save'&&!s.pdfPreparedAt){el.checked=false;toast('Prepare a PDF and save it before confirming.');return;}if(el.checked&&key==='folder'&&!s.fields.folder?.trim()){el.checked=false;toast('Record the folder where you saved your PDF.');return;}if(!el.checked){for(const step of G.steps.slice(i))delete s.guideChecks[step.id];}else{s.guideChecks[key]={at:new Date().toISOString(),selfConfirmed:true};if(key==='confirm')s.submissionHistory.push({at:new Date().toISOString(),reportPreparedAt:s.pdfPreparedAt,type:'Student reports Teams Turned in status; not independently verified'});}touch(false);render();return;}if(['SELECT'].includes(el.tagName)||['checkbox','radio'].includes(el.type))recordInput(el);});
document.addEventListener('keydown',ev=>{if(ev.target.dataset.act==='plot-point'&&['Enter',' '].includes(ev.key)){ev.preventDefault();ev.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('click',async ev=>{if(ev.target.id==='shot-marker-image'&&s?.teacher){const im=ev.target,rect=im.getBoundingClientRect(),ratio=Math.min(rect.width/im.naturalWidth,rect.height/im.naturalHeight),iw=im.naturalWidth*ratio,ih=im.naturalHeight*ratio,x=(ev.clientX-rect.left-(rect.width-iw)/2)/iw,y=(ev.clientY-rect.top-(rect.height-ih)/2)/ih;if(x<0||x>1||y<0||y>1)return;const key=G.screenshotKey(shotRoute(),shotIdx());config.screenshotOverrides[key].point={x,y};persistConfig();updateShotPreview();toast('Highlight placed. Export config.js to share it.');return;}const b=ev.target.closest('[data-act]');if(!b)return;if(b.disabled)return;const a=b.dataset.act,id=b.dataset.id;
if(a==='close-modal'){closeModal();return;}if(a==='resume'){const st=load(KEY);if(st?.schema===1&&st?.q&&st?.fields){s=st;pdf=null;render();}else toast('The saved lesson is not compatible. Start a new lesson.');return;}if(!s)return;
switch(a){case'prev':gotoStage(s.stage-1);break;case'next':gotoStage(s.stage+1);break;case'stage':gotoStage(Number(b.dataset.index));break;
case'sub':case'sub-next':case'sub-prev':{const group=b.dataset.group;const max=group==='main1'?5:2;if(a==='sub-next'&&s.sub[group]===max){gotoStage(s.stage+1);break;}let n=a==='sub'?Number(b.dataset.index):s.sub[group]+(a==='sub-next'?1:-1);n=Math.max(0,Math.min(max,n));if(!canSub(group,n)){toast('Make and check the current prediction, and record the requested explanation first.');break;}s.sub[group]=n;render();document.getElementById('main').scrollIntoView({block:'start'});break;}
case'check-q':{const q=s.q[id];if(q?.value===undefined){toast('Choose an answer, or choose “I am not sure yet”.');break;}q.history.push({value:q.value,correct:q.value===L.questions[id].correct,at:new Date().toISOString()});touch();render();document.getElementById('q-'+id)?.scrollIntoView({block:'center'});break;}
case'reset-trace':s.steps[id]=0;touch(false);render();break;case'step-trace':s.steps[id]=Math.min((s.steps[id]||0)+1,M.trace(L.examples[id].code,L.examples[id].start).length-1);touch(false);render();break;
case'check-route':{const keys=['traceX2','traceY2','traceDir2','traceX3','traceY3','traceDir3'];if(keys.some(k=>!String(s.fields[k]??'').trim())||!(s.fields.traceExplain?.trim()||s.fields.traceSpoken)){toast('Complete both rows and add an explanation, or mark that you explained aloud.');break;}const f={...s.fields};const correct=Number(f.traceX2)===0&&Number(f.traceY2)===100&&f.traceDir2==='Up'&&Number(f.traceX3)===200&&Number(f.traceY3)===100&&f.traceDir3==='Right';s.traceAttempts.push({at:new Date().toISOString(),fields:f,correct});touch();render();break;}
case'plot-point':addPoint(Number(b.dataset.x),Number(b.dataset.y));break;case'add-point':if(!String(s.fields.plotX??'').trim()||!String(s.fields.plotY??'').trim()){toast('Enter x and y first.');break;}addPoint(Number(s.fields.plotX),Number(s.fields.plotY));break;case'undo-point':if(!s.checkpoint)s.checkpointDraft.points.pop();touch();render();break;case'clear-points':if(!s.checkpoint)s.checkpointDraft.points=[];touch();render();break;
case'submit-checkpoint':{if(s.checkpoint)break;const cp=readCheckpoint();if(!cp.mode){toast('Choose how you completed the checkpoint.');break;}if((!cp.syntax||!cp.x||!cp.y||!cp.heading||cp.points.length!==3||!cp.reason||!cp.comment)&&!confirm('Some answers are incomplete. Save this first attempt as it is? Your teacher will see what you completed.'))break;s.checkpoint=cp;touch();render();toast('First checkpoint saved unchanged. Later corrections are recorded separately.');break;}
case'save-correction':{const text=s.fields.cpCorrection?.trim();if(!text){toast('Write the correction and why you would change it.');break;}s.checkpointCorrections.push({text,at:new Date().toISOString()});s.fields.cpCorrection='';touch();render();break;}
case'run-extension':try{const st=M.trace(s.extensionCode).at(-1),xs=[0,st.x,...st.segments.flatMap(p=>[p.x1,p.x2])],ys=[0,st.y,...st.segments.flatMap(p=>[p.y1,p.y2])];s.extensionResult=st;s.extensionBounds={minX:Math.floor((Math.min(-40,...xs)-20)/20)*20,maxX:Math.ceil((Math.max(40,...xs)+20)/20)*20,minY:Math.floor((Math.min(-40,...ys)-20)/20)*20,maxY:Math.ceil((Math.max(40,...ys)+20)/20)*20,step:Math.max(...xs)-Math.min(...xs)>500?100:20};touch();render();}catch(err){document.getElementById('extension-error').textContent=err.message;}break;
case'profile':profileModal();break;
case'teacher-assist':modal('Teacher assistance','<p>This lets the student continue with incomplete evidence. It does not mark missing answers as complete or reveal checkpoint answers. The reason will appear in the PDF.</p><div class="field"><label for="assist-name">Enter teacher</label><input id="assist-name" autocomplete="off"></div><div class="field"><label for="assist-reason">Reason / support agreed</label><textarea id="assist-reason" maxlength="250"></textarea></div><button data-act="apply-assist">Release incomplete evidence</button><p class="hint">Convenience control, not a password or secure verification.</p>');break;
case'apply-assist':{const reason=document.getElementById('assist-reason').value.trim();if(document.getElementById('assist-name').value.trim().toLowerCase()!=='teacher'||!reason){toast('Enter teacher and a reason.');break;}s.teacherRelease=true;s.overrides.push({reason,at:new Date().toISOString(),type:'Teacher release entered locally; not authenticated'});touch();closeModal();render();toast('Incomplete evidence released. Missing answers remain visible in the report.');break;}
case'reference':referenceModal();break;case'sources':modal('Sources & privacy',sourcesHTML());break;case'map':modal('Week 2 practice map','<img src="assets/school-map.png" alt="School wayfinding practice map from the Week 2 project" style="width:100%"><p>This is the practice map from the previous lesson, not a live navigation map.</p>');break;
case'support':coreSupport('Student requested teacher help');modal('Ask your teacher','<p>'+t(T('Raise your hand and show the part you are working on. Explain what you have already tried. Keep this tab open.','举手并展示正在做的部分，说说已经尝试了什么。保持页面打开。','손을 들고 지금 풀고 있는 부분을 보여 주세요. 무엇을 시도했는지 설명하세요. 이 탭을 열어 두세요.'))+'</p><p class="hint">Your request is recorded in the report. This button does not send a message or notification to your teacher.</p>');break;
case'guide-step':s.guideStep=Number(b.dataset.index);touch(false);render();break;case'guide-prev':s.guideStep=Math.max(0,s.guideStep-1);touch(false);render();break;case'guide-next':if(!s.teacher&&!s.guideChecks[G.steps[s.guideStep].id]){toast('Complete this action and confirm it before continuing.');break;}if(s.guideStep===8)gotoStage(9);else{s.guideStep++;touch(false);render();}break;
case'guide-help':helpModal(id);break;case'enlarge-guide':modal('Enlarged guide picture',b.closest('.shot-label').nextElementSibling.innerHTML);break;
case'preview-report':previewReport();break;case'prepare-pdf':await preparePDF();break;case'save-pdf':await savePDF();break;case'download-pdf':if(pdf)download(pdf.blob,pdf.filename);break;case'open-pdf':if(pdf){const u=URL.createObjectURL(pdf.blob);window.open(u,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(u),120000);toast('Use the viewer’s save or Share control to keep a copy.');}break;
case'print-report':s.pdfPreparedAt=new Date().toISOString();s.pdfVersion=s.evidenceVersion;save();document.title=G.filename(s).replace(/\.pdf$/,'');window.print();toast('Check the saved PDF in your chosen folder. The print dialog does not confirm saving.');break;
case'check-practice':{const q=root.TurtleQuiz[quizIndex],v=s.quiz.answers[q.id];if(v===undefined){toast('Choose an answer first.');break;}s.quiz.history.push({id:q.id,value:v,at:new Date().toISOString()});touch(false);render();break;}
case'quiz-prev':quizIndex=Math.max(0,quizIndex-1);render();break;case'quiz-next':if(!s.teacher&&!s.quiz.history.some(h=>h.id===root.TurtleQuiz[quizIndex].id)){toast('Check your answer before moving to the next question.');break;}if(quizIndex===14)quizResult();else{quizIndex++;render();}break;
case'teacher':teacherModal();break;case'answer-key':if(s.teacher)answerKey();break;case'project-guide':if(s.teacher)projectGuide();break;
case'export-config':if(s.teacher)download(new Blob(['// Teacher configuration; no student answers.\nwindow.LESSON_CONFIG = '+JSON.stringify(config,null,2)+';\n'],{type:'text/javascript'}),'config.js');break;
case'share-setup':if(s.teacher){if(location.protocol==='file:'){toast('Host the app first to make a student web link, or export config.js for deployment.');break;}const cfg={assignmentTitle:config.assignmentTitle,teamsUrl:config.teamsUrl,gimkitUrl:config.gimkitUrl},u=location.origin+location.pathname+'#setup='+btoa(unescape(encodeURIComponent(JSON.stringify(cfg))));modal('Configured student link','<p>Share this link after hosting the app. It carries the assignment title and activity destinations, but not screenshots or student data.</p><textarea rows="6" readonly id="setup-link">'+E(u)+'</textarea><button data-act="copy-link">Copy link</button>');}break;
case'copy-link':{const el=document.getElementById('setup-link');el.select();try{await navigator.clipboard.writeText(el.value);toast('Configured link copied.');}catch(e){toast('The link is selected. Use your device’s Copy command.');}break;}
case'remove-shot':if(s.teacher){delete config.screenshotOverrides[G.screenshotKey(shotRoute(),shotIdx())];persistConfig();updateShotPreview();}break;
case'end-session':if(confirm('Clear this student’s answers from this browser? Export and save the PDF first. This does not remove files or work already submitted to Teams.')){localStorage.removeItem(KEY);s=null;pdf=null;closeModal();landing();}break;
}
});
window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')save();});
root.App={refreshQuestion(id){const el=document.getElementById('q-'+id);if(el&&L.questions[id])el.outerHTML=question(id);},get state(){return s;},get config(){return config;},get pdf(){return pdf;},touch,E,t,codebox,plotHTML,missingCore,complete,save,render,toast,cleanConfig,validURL,sources};
landing();
})(window);
